import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, Easing } from '../remotionShim';
// --- Google Fonts Loader ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- Schema ---


export type GrowthVsScaleProps = Record<string, any>;

const GrowthVsScale: React.FC<GrowthVsScaleProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 4,
  
  axisColor = "#FFFFFF",
  labelColor = "#FFFFFF",
  growthLineColor = "#FFFFFF",
  scaleLineColor = "#CCBA78",
  
  showYAxis = true,
  showXAxis = true,
  showLabels = true,
  showGrowthLine = true,
  showScaleLine = true,
  
  labelYStart = "$3M",
  labelYEnd = "$30M",
  labelXStart = "0",
  labelXMid = "3 YRS",
  labelXEnd = "10 YRS",
  growthLabelText = "GROWTH",
  scaleLabelText = "SCALE",
  
  strokeWidthAxis = 4,
  strokeWidthGraph = 6,
  labelFontSize = 32,
  lineLabelFontSize = 28,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();

  // Background Logic
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // --- Animation Timing Configuration (Seconds) ---
  // Overlapping timings for a more subtle feel
  const tAxis = 1.5; 
  const tLabels = 1.2;
  const tGrowth = 2.0;
  const tScale = 2.2;

  // Start Frames (Overlapping)
  const fStart = 0;
  const fAxisStart = 0;
  const fLabelsStart = 10; // Start fading labels in very early
  const fGrowthStart = 15; // Start growth line shortly after axes start
  
  // Requested: Scale line comes in at 1 second
  const fScaleStart = fps * 1; 

  // End Frames
  const fYAxisEnd = fAxisStart + tAxis * fps;
  const fXAxisEnd = fAxisStart + tAxis * fps;
  const fLabelsEnd = fLabelsStart + tLabels * fps;
  const fGrowthEnd = fGrowthStart + tGrowth * fps;
  const fScaleEnd = fScaleStart + tScale * fps;

  // --- Coordinate System (ViewBox 0 0 1600 900) ---
  const PADDING_LEFT = 150;
  const PADDING_BOTTOM = 100;
  const VIEW_WIDTH = 1600;
  const VIEW_HEIGHT = 900;
  
  const ORIGIN_X = PADDING_LEFT;
  const ORIGIN_Y = VIEW_HEIGHT - PADDING_BOTTOM;
  
  const MAX_X = VIEW_WIDTH - 50; // Right edge
  const MAX_Y = 100; // Top edge
  
  const GRAPH_WIDTH = MAX_X - ORIGIN_X;
  const GRAPH_HEIGHT = ORIGIN_Y - MAX_Y;

  // Points
  const pOrigin = { x: ORIGIN_X, y: ORIGIN_Y };
  const pYTop = { x: ORIGIN_X, y: MAX_Y };
  const pXRight = { x: MAX_X, y: ORIGIN_Y };

  // Growth Line (Linear): Ends at 10 YRS (Full Width)
  const pGrowthEnd = { x: MAX_X, y: MAX_Y };

  // Scale Line (Hockey Stick): Ends at 3 YRS (30% Width)
  // 3 years / 10 years = 0.3
  const scaleTargetX = ORIGIN_X + (GRAPH_WIDTH * 0.3);
  const pScaleEnd = { x: scaleTargetX, y: MAX_Y };

  // Bezier Control Points for Hockey Stick
  // Start flat, curve up late
  const cp1Scale = { 
    x: ORIGIN_X + ((scaleTargetX - ORIGIN_X) * 0.6), 
    y: ORIGIN_Y 
  };
  const cp2Scale = { 
    x: scaleTargetX, 
    y: ORIGIN_Y - (GRAPH_HEIGHT * 0.2) 
  };

  // --- Interpolations ---

  // 1. Y Axis (Draw Up) - Subtle easing
  const yAxisProgress = interpolate(frame, [fStart, fYAxisEnd], [0, 1], {
    extrapolateRight: "clamp",
    easing: Easing.inOut(Easing.quad),
  });

  // 2. X Axis (Draw Right) - Subtle easing
  const xAxisProgress = interpolate(frame, [fStart, fXAxisEnd], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
    easing: Easing.inOut(Easing.quad),
  });

  // 3. Labels (Fade In)
  const labelOpacity = interpolate(frame, [fLabelsStart, fLabelsEnd], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
  });

  // 4. Growth Line (Draw Diagonal) - Subtle easing
  const growthProgress = interpolate(frame, [fGrowthStart, fGrowthEnd], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
    easing: Easing.inOut(Easing.quad),
  });

  // 5. Scale Line (Draw Curve) - Subtle easing
  const scaleProgress = interpolate(frame, [fScaleStart, fScaleEnd], [0, 1], {
    extrapolateRight: "clamp",
    extrapolateLeft: "clamp",
    easing: Easing.out(Easing.quad),
  });

  // Line Label Opacities (Fade in towards end of line drawing)
  const growthLabelOpacity = interpolate(growthProgress, [0.7, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const scaleLabelOpacity = interpolate(scaleProgress, [0.7, 1], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Path Definitions
  const pathGrowth = `M ${pOrigin.x} ${pOrigin.y} L ${pGrowthEnd.x} ${pGrowthEnd.y}`;
  const pathScale = `M ${pOrigin.x} ${pOrigin.y} C ${cp1Scale.x} ${cp1Scale.y}, ${cp2Scale.x} ${cp2Scale.y}, ${pScaleEnd.x} ${pScaleEnd.y}`;
  
  // Approximate Lengths for DashOffset
  const lenGrowth = Math.hypot(pGrowthEnd.x - pOrigin.x, pGrowthEnd.y - pOrigin.y); 
  const lenScale = 2000; // Overestimate for curve on wider screen

  return (
    <AbsoluteFill style={{ backgroundColor: finalBgColor }}>
      <div 
        style={{ 
          width: "100%", 
          height: "100%", 
          display: "flex", 
          justifyContent: "center", 
          alignItems: "center",
          fontFamily: "Inter, sans-serif",
        }}
      >
        <svg 
          width="90%" 
          height="90%" 
          viewBox={`0 0 ${VIEW_WIDTH} ${VIEW_HEIGHT}`}
          style={{ overflow: "visible" }}
        >
          {/* --- AXES --- */}
          {showYAxis && (
            <line
              x1={pOrigin.x}
              y1={pOrigin.y}
              x2={pYTop.x}
              y2={pYTop.y}
              stroke={axisColor}
              strokeWidth={strokeWidthAxis}
              strokeLinecap="round"
              strokeDasharray={GRAPH_HEIGHT}
              strokeDashoffset={GRAPH_HEIGHT * (1 - yAxisProgress)}
            />
          )}

          {showXAxis && (
            <line
              x1={pOrigin.x}
              y1={pOrigin.y}
              x2={pXRight.x}
              y2={pXRight.y}
              stroke={axisColor}
              strokeWidth={strokeWidthAxis}
              strokeLinecap="round"
              strokeDasharray={GRAPH_WIDTH}
              strokeDashoffset={GRAPH_WIDTH * (1 - xAxisProgress)}
            />
          )}

          {/* --- LABELS --- */}
          <g style={{ opacity: showLabels ? labelOpacity : 0 }}>
            {/* Y Labels */}
            <text 
              x={ORIGIN_X - 20} 
              y={ORIGIN_Y} 
              fill={labelColor} 
              fontSize={labelFontSize} 
              textAnchor="end" 
              dominantBaseline="middle"
              fontWeight="600"
            >
              {labelYStart}
            </text>
            <text 
              x={ORIGIN_X - 20} 
              y={MAX_Y} 
              fill={labelColor} 
              fontSize={labelFontSize} 
              textAnchor="end" 
              dominantBaseline="middle"
              fontWeight="600"
            >
              {labelYEnd}
            </text>

            {/* X Labels */}
            <text 
              x={ORIGIN_X} 
              y={ORIGIN_Y + 60} 
              fill={labelColor} 
              fontSize={labelFontSize} 
              textAnchor="middle" 
              fontWeight="600"
            >
              {labelXStart}
            </text>
            
            {/* 3 YRS Mark */}
            <text 
              x={scaleTargetX} 
              y={ORIGIN_Y + 60} 
              fill={labelColor} 
              fontSize={labelFontSize} 
              textAnchor="middle" 
              fontWeight="600"
            >
              {labelXMid}
            </text>
             {/* Tick mark for 3yrs */}
             <line 
                x1={scaleTargetX} 
                y1={ORIGIN_Y} 
                x2={scaleTargetX} 
                y2={ORIGIN_Y + 15} 
                stroke={axisColor} 
                strokeWidth={strokeWidthAxis / 2} 
             />

            {/* 10 YRS Mark */}
            <text 
              x={MAX_X} 
              y={ORIGIN_Y + 60} 
              fill={labelColor} 
              fontSize={labelFontSize} 
              textAnchor="middle" 
              fontWeight="600"
            >
              {labelXEnd}
            </text>
            <line 
                x1={MAX_X} 
                y1={ORIGIN_Y} 
                x2={MAX_X} 
                y2={ORIGIN_Y + 15} 
                stroke={axisColor} 
                strokeWidth={strokeWidthAxis / 2} 
             />
          </g>

          {/* --- GROWTH LINE (Linear) --- */}
          {showGrowthLine && (
            <>
              <path
                d={pathGrowth}
                fill="none"
                stroke={growthLineColor}
                strokeWidth={strokeWidthGraph}
                strokeLinecap="round"
                strokeDasharray={lenGrowth}
                strokeDashoffset={lenGrowth * (1 - growthProgress)}
              />
              <text
                x={pGrowthEnd.x}
                y={pGrowthEnd.y - 30}
                fill={growthLineColor}
                fontSize={lineLabelFontSize}
                textAnchor="end"
                fontWeight="700"
                style={{ opacity: growthLabelOpacity }}
              >
                {growthLabelText}
              </text>
            </>
          )}

          {/* --- SCALE LINE (Hockey Stick) --- */}
          {showScaleLine && (
            <>
              <path
                d={pathScale}
                fill="none"
                stroke={scaleLineColor}
                strokeWidth={strokeWidthGraph}
                strokeLinecap="round"
                strokeDasharray={lenScale}
                strokeDashoffset={lenScale * (1 - scaleProgress)}
              />
              <text
                x={pScaleEnd.x}
                y={pScaleEnd.y - 30}
                fill={scaleLineColor}
                fontSize={lineLabelFontSize}
                textAnchor="middle"
                fontWeight="700"
                style={{ opacity: scaleLabelOpacity }}
              >
                {scaleLabelText}
              </text>
            </>
          )}
        </svg>
      </div>
    </AbsoluteFill>
  );
};

export default GrowthVsScale;